[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$JobRoot,[Parameter(Mandatory=$true)][string]$AttemptId,[string]$RepositoryRoot)
$ErrorActionPreference='Stop';if(-not $RepositoryRoot){$RepositoryRoot=Split-Path -Parent $PSScriptRoot};$RepositoryRoot=[IO.Path]::GetFullPath($RepositoryRoot);$JobRoot=[IO.Path]::GetFullPath($JobRoot);$attemptRoot=Join-Path $JobRoot (Join-Path 'output' $AttemptId);if(Test-Path $attemptRoot){throw "Attempt exists"};$source=Join-Path $RepositoryRoot 'src\fg_conv\rtx_custom_conv2_oracle.cpp';$base=Join-Path $RepositoryRoot 'src\fg_conv\rtx_oracle.cpp';$contract=Join-Path $RepositoryRoot 'src\fg_conv\custom_conv2_contract.h';$module=Join-Path $JobRoot 'inputs\cu-module-000057.bin';$manifest=Join-Path $JobRoot 'inputs\runtime-default-buffers-post-evaluate-0.manifest.json';foreach($f in @($source,$base,$contract,$module,$manifest)){if(-not(Test-Path $f -PathType Leaf)){throw "Missing $f"}}
$cudaPath=$env:CUDA_PATH;if(-not $cudaPath){$cudaPath='C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$install=&$vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vcvars=Join-Path $install 'VC\Auxiliary\Build\vcvars64.bat';$build=Join-Path $attemptRoot 'build';New-Item -ItemType Directory $build|Out-Null;$binary=Join-Path $build 'fg-custom-conv2-rtx.exe';$obj=Join-Path $build 'oracle.obj';$log=Join-Path $build 'compile.log';$cmd='"{0}" >nul && cl.exe /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /Zc:__cplusplus /utf-8 /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && link.exe /nologo /OUT:"{5}" "{2}" "{6}" bcrypt.lib >>"{4}" 2>&1' -f $vcvars,(Join-Path $cudaPath 'include'),$obj,$source,$log,$binary,(Join-Path $cudaPath 'lib\x64\cuda.lib');&$env:ComSpec /d /s /c $cmd;if($LASTEXITCODE -ne 0){throw "Build failed $log"}
$rows=@();foreach($launch in 60..67){$layer="l$launch";$wt=118+4*($launch-60);$bt=$wt+2;$weights=Join-Path $JobRoot ('inputs\default-token-{0:D6}-post-eval0.bin' -f $wt);$bias=Join-Path $JobRoot ('inputs\default-token-{0:D6}-post-eval0.bin' -f $bt);$root=Join-Path $attemptRoot $layer;New-Item -ItemType Directory $root|Out-Null;$receipts=@();foreach($poison in @('a5','5a')){foreach($ord in @('a','b')){$id="$layer-poison-$poison-process-$ord";$run=Join-Path $root $id;New-Item -ItemType Directory $run|Out-Null;$p=Start-Process $binary -ArgumentList @($layer,$module,$weights,$bias,$run,$id,$poison) -NoNewWindow -Wait -PassThru -RedirectStandardOutput (Join-Path $run 'stdout.log') -RedirectStandardError (Join-Path $run 'stderr.log');if($p.ExitCode -ne 0){throw "Run failed $id"};$receipts+=Get-Content (Join-Path $run 'run-receipt.json') -Raw|ConvertFrom-Json}};$hash=@($receipts|%{$_.output_sha256}|Sort-Object -Unique);$pids=@($receipts|%{$_.process_id}|Sort-Object -Unique);if($hash.Count -ne 1 -or $pids.Count -ne 4){throw "Gate failed $layer"};$rows+=[ordered]@{layer_id=$layer;output_sha256=$hash[0]}}
$receipt=[ordered]@{schema='neuralstudio.fg.custom-conv2-rig.v1';job_id=(Split-Path -Leaf $JobRoot);attempt_id=$AttemptId;gpu=(&nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader,nounits|Select-Object -First 1).Trim();module_sha256=(Get-FileHash $module -Algorithm SHA256).Hash.ToLowerInvariant();manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash.ToLowerInvariant();source_sha256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant();contract_sha256=(Get-FileHash $contract -Algorithm SHA256).Hash.ToLowerInvariant();binary_sha256=(Get-FileHash $binary -Algorithm SHA256).Hash.ToLowerInvariant();layers=$rows;layer_count=8;fresh_process_count=32;address_fields_recorded=$false;result='pass'};$u=New-Object Text.UTF8Encoding($false);$rp=Join-Path $attemptRoot 'rig-receipt.json';[IO.File]::WriteAllText($rp,(($receipt|ConvertTo-Json -Depth 6)+"`n"),$u);$rh=(Get-FileHash $rp -Algorithm SHA256).Hash.ToLowerInvariant();[IO.File]::WriteAllText((Join-Path $attemptRoot 'rig-receipt.sha256'),($rh+"  rig-receipt.json`n"),$u);Write-Host "attempt_root=$attemptRoot";Write-Host "rig_receipt_sha256=$rh";Write-Host 'result=pass'
